bool restorationFixture(const File& file,float offset=.2f){AudioBuffer<float> audio(2,96000);for(int i=0;i<audio.getNumSamples();++i){audio.setSample(0,i,offset+(float)(.15*std::sin(2*MathConstants<double>::pi*440*i/48000)));audio.setSample(1,i,-.1f+(float)(.08*std::sin(2*MathConstants<double>::pi*660*i/48000)));}file.getParentDirectory().createDirectory();TemporaryFile temp(file);std::unique_ptr<OutputStream> out(temp.getFile().createOutputStream());WavAudioFormat wav;auto writer=out?wav.createWriterFor(out,AudioFormatWriterOptions{}.withSampleRate(48000).withNumChannels(2).withBitsPerSample(32).withSampleFormat(AudioFormatWriterOptions::SampleFormat::floatingPoint)):nullptr;if(!writer||!writer->writeFromAudioSampleBuffer(audio,0,audio.getNumSamples()))return false;writer.reset();out.reset();return temp.overwriteTargetFileWithTemporary();}
AlertWindow* restorationDialog(){return dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());}
void restorationSnapshot(AlertWindow* d,const File& file){if(!d)return;FileOutputStream out(file);if(out.openedOk())PNGImageFormat().writeImageToStream(d->createComponentSnapshot(d->getLocalBounds()),out);}
Component* restorationForm(AlertWindow* d){return d?d->findChildWithID("restoration-form"):nullptr;}
