    auto saved=project;auto savedCurrent=currentFile;auto undo=undoStack,redo=redoStack;auto wave=waveFile;auto* sample=waveSample;auto history=waveHistory,forward=waveRedoHistory;auto markers=waveMarkers;double a=waveStart,b=waveEnd,view=waveViewStart,span=waveSpan;auto settings=restorationOptions;int track=selectedTrack;bool wasDirty=dirty;
    perform(stop);releaseKeys();cancelNoteTool();closeCommandPalette();discardRestoration();project=emptyProject();currentFile={};selectedTrack=7;publish();undoStack.clear();redoStack.clear();auto original=JSON::toString(projectToJson(project));auto projectRevision=revision;
    auto file=folder.getChildFile("restoration-source.wav");check(restorationFixture(file),"create original stereo restoration fixture");auto hash=SHA256(file).toHexString();openWaveform(file);setSize(1440,940);resetLayout();showPane(wavePane);RestorationOptions dc;
