    check(!searchCommands(paletteEntries(),"audio restoration").empty(),"Ctrl+P discovers native audio restoration");showRestorationSettings();auto* d=restorationDialog();auto* form=restorationForm(d);check(form&&form->findChildWithID("restoration-mode")&&form->findChildWithID("restoration-threshold"),"compact restoration settings exposes three modes and actual-unit controls");if(d){restorationSnapshot(d,folder.getChildFile("restoration-settings.png"));d->exitModalState(0);}check(waveFile==file&&waveHistory.empty()&&!restorationTask,"cancelling configuration retains waveform and history");
    check(beginRestoration(dc,waveRevision,false)&&!beginRestoration(dc,waveRevision,false),"one immutable restoration worker starts and duplicate jobs reject");check(wait()&&restorationCurrent()&&waveFile==file&&waveHistory.empty()&&restorationFile.existsAsFile(),"processing creates only an unapplied local audition copy");check(restorationPreview&&std::abs(restorationStats.dcAfter[0])<1e-7&&std::abs(restorationStats.dcAfter[1])<1e-7,"preview measures independent DC removal on actual decoded source audio");
    auto candidate=restorationFile;auto* processed=restorationPreview;showRestorationReview();d=restorationDialog();auto* report=d?dynamic_cast<TextEditor*>(d->findChildWithID("restoration-report")):nullptr;check(report&&report->isReadOnly()&&report->getText().contains("Changed samples")&&report->getText().contains("No normalization"),"read-only review shows measured changes and processing boundaries");if(d){restorationSnapshot(d,folder.getChildFile("restoration-review.png"));d->exitModalState(2);}check(auditionRestoration(true),"restored selection can be auditioned without applying it");AudioBuffer<float> block(2,4096);engine->render(block.getWritePointer(0),block.getWritePointer(1),4096);check(engine->previewPlaying.load()&&block.getMagnitude(0,0,4096)>.02f&&waveFile==file&&waveHistory.empty(),"audition reaches real Engine audio while original editor/history stay intact");
    check(applyRestoration()&&waveFile==candidate&&waveSample==processed&&waveHistory.size()==1&&waveSample->sampleRate==48000&&waveSample->audio.getNumSamples()==96000,"Apply opens verified float audio as one independent waveform history entry");AudioFormatManager fm;fm.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(fm.createReaderFor(candidate));check(reader&&reader->usesFloatingPointData&&reader->lengthInSamples==96000,"restored WAV preserves floating point samples, rate and frame count");perform(waveUndo);check(waveFile==file&&waveHistory.empty()&&waveRedoHistory.size()==1,"one waveform Undo restores the exact original file");perform(waveRedo);check(waveFile==candidate&&waveHistory.size()==1,"waveform Redo restores the retained restoration copy");
    openWaveform(file);waveStart=.25;waveEnd=.75;waveViewStart=.2;waveSpan=.6;waveMarkers={12000};check(beginRestoration(dc,waveRevision,false)&&wait()&&applyRestoration()&&waveStart==.25&&waveEnd==.75&&waveViewStart==.2&&waveSpan==.6&&waveMarkers.empty(),"selected restoration retains timing/zoom while clearing stale analysis markers");perform(waveUndo);check(waveFile==file&&waveStart==.25&&waveEnd==.75&&waveViewStart==.2&&waveSpan==.6,"audio Undo retains original selection and view");
    check(beginRestoration(dc,waveRevision,false),"cancellable restoration job starts");discardRestoration();check(wait()&&!restorationPreview&&waveFile==file&&waveHistory.empty()&&status.contains("cancelled"),"cancelling background restoration retains editor and history");
    check(beginRestoration(dc,waveRevision,false),"source-bound restoration starts");waveStart=.3;++waveRevision;check(wait()&&!restorationPreview&&waveFile==file&&status.contains("changed"),"changed selection rejects a completed stale preview");
    check(beginRestoration(dc,waveRevision,false)&&wait(),"discardable preview completes");auto discarded=restorationFile;discardRestoration();check(!discarded.exists()&&!restorationPreview&&waveFile==file,"discard removes only the unapplied owned preview file");
