    check(!beginRestoration(dc,waveRevision-1,false),"stale configuration cannot start processing");waveEditBusy=true;check(!beginRestoration(dc,waveRevision,false),"sample-rate conversion blocks concurrent restoration start");waveEditBusy=false;exporting.store(true);check(!beginRestoration(dc,waveRevision,false),"export blocks restoration start");exporting.store(false);
